package com.smarthospital.controller;
import com.smarthospital.model.*;import com.smarthospital.util.*;import javax.servlet.*;import javax.servlet.http.*;import javax.servlet.annotation.*;import java.io.*;import java.sql.*;import java.time.*;import java.util.*;
@WebServlet("/duties") public class DutyServlet extends HttpServlet{
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");if(Access.isStaff(u)){resp.sendError(403);return;}try(Connection c=DB.getConnection()){List<Map<String,Object>>rows=new ArrayList<>();List<Object>ps=new ArrayList<>();String pred=Access.departmentPredicate(u,"d.department_id",ps,c);String q="SELECT d.duty_id,d.duty_name,d.duty_date,d.start_time,d.end_time,d.priority,d.status,dp.department_name,r.role_name,COALESCE(GROUP_CONCAT(s.name ORDER BY s.name SEPARATOR ', '),'Unassigned') FROM duties d JOIN departments dp ON d.department_id=dp.department_id JOIN roles r ON d.role_id=r.role_id LEFT JOIN duty_assignments da ON d.duty_id=da.duty_id AND da.status<>'CANCELLED' LEFT JOIN staff s ON da.staff_id=s.staff_id WHERE "+pred+" GROUP BY d.duty_id ORDER BY d.duty_date DESC,d.start_time DESC";try(PreparedStatement p=c.prepareStatement(q)){for(int i=0;i<ps.size();i++)p.setObject(i+1,ps.get(i));try(ResultSet x=p.executeQuery()){while(x.next()){Map<String,Object>m=new HashMap<>();for(int i=1;i<=10;i++)m.put("c"+i,x.getObject(i));rows.add(m);}}}req.setAttribute("rows",rows);req.setAttribute("departments",departments(c,u));req.setAttribute("roles",list(c,"roles","role_id","role_name"));req.setAttribute("skills",list(c,"skills","skill_id","skill_name"));req.getRequestDispatcher("/duties.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{User u=(User)req.getSession().getAttribute("user");if(Access.isStaff(u)){resp.sendError(403);return;}try(Connection c=DB.getConnection()){String name=req.getParameter("duty_name");int dept=Integer.parseInt(req.getParameter("department_id")),role=Integer.parseInt(req.getParameter("role_id"));if(Access.isSupervisor(u)&&!Access.supervisorHasDepartment(c,u.id(),dept))throw new SecurityException("You can create duties only for your assigned department(s).");LocalDate date=LocalDate.parse(req.getParameter("duty_date"));LocalTime start=LocalTime.parse(req.getParameter("start_time")),end=LocalTime.parse(req.getParameter("end_time"));if(name==null||name.trim().isEmpty())throw new IllegalArgumentException("Duty name is required.");if(!end.isAfter(start))throw new IllegalArgumentException("End time must be after start time.");if(date.isBefore(LocalDate.now()))throw new IllegalArgumentException("Duty date cannot be in the past.");String q="INSERT INTO duties(duty_name,department_id,role_id,duty_date,start_time,end_time,priority,description,created_by) VALUES(?,?,?,?,?,?,?,?,?)";try(PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setString(1,name.trim());p.setInt(2,dept);p.setInt(3,role);p.setDate(4,java.sql.Date.valueOf(date));p.setTime(5,Time.valueOf(start));p.setTime(6,Time.valueOf(end));p.setString(7,req.getParameter("priority"));p.setString(8,req.getParameter("description"));p.setInt(9,u.id());p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){if(k.next()){String[]skills=req.getParameterValues("skill_id");if(skills!=null)try(PreparedStatement s=c.prepareStatement("INSERT INTO duty_required_skills(duty_id,skill_id) VALUES(?,?)")){for(String v:skills){s.setInt(1,k.getInt(1));s.setInt(2,Integer.parseInt(v));s.addBatch();}s.executeBatch();}}}}Audit.log(u.id(),"DUTY_CREATED",name);resp.sendRedirect(req.getContextPath()+"/duties");}catch(Exception e){resp.sendError(400,e.getMessage());}}
 private List<Map<String,Object>> departments(Connection c,User u)throws Exception{List<Map<String,Object>>l=new ArrayList<>();List<Object>ps=new ArrayList<>();String pred=Access.departmentPredicate(u,"department_id",ps,c);try(PreparedStatement p=c.prepareStatement("SELECT department_id,department_name FROM departments WHERE "+pred+" ORDER BY department_name")){for(int i=0;i<ps.size();i++)p.setObject(i+1,ps.get(i));try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object>m=new HashMap<>();m.put("id",r.getInt(1));m.put("name",r.getString(2));l.add(m);}}}return l;}
 private List<Map<String,Object>> list(Connection c,String t,String id,String name)throws Exception{List<Map<String,Object>>l=new ArrayList<>();try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT "+id+","+name+" FROM "+t+" ORDER BY "+name)){while(r.next()){Map<String,Object>m=new HashMap<>();m.put("id",r.getInt(1));m.put("name",r.getString(2));l.add(m);}}return l;}
}
